// Generates lib/engine.js and lib/system.js from counter.html so the server uses the SAME pricing engine,
// guardrails and system prompt as the browser. counter.html stays the single source of truth.
// Run: node scripts/gen-engine.js         (npm run build also runs it)
// Check only: node scripts/gen-engine.js --check   (exits 1 if the generated files are out of date)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const html = fs.readFileSync(path.join(root, 'counter.html'), 'utf8');

const a = html.indexOf('/* ============ pure engine ============ */');
const b = html.indexOf('/* ============ state ============ */');
if (a < 0 || b < a) throw new Error('engine markers not found in counter.html');
const engine =
  '// GENERATED by scripts/gen-engine.js from counter.html. Do not edit by hand.\n' +
  html.slice(a, b) +
  '\nexport { analyze, special, refusal, checkRate, missingTerms, parseTerms, parsePersona, parseAmount, INR };\n';

// The system prompt is the SYSTEM template string in counter.html. Evaluate that one const safely.
const s0 = html.indexOf('const SYSTEM = `');
const s1 = html.indexOf('`;', s0) + 2;
const SYSTEM = new Function(html.slice(s0, s1) + '\nreturn SYSTEM;')();
const marker = 'CONTEXT YOU HAVE ABOUT THIS CREATOR:';
const toneAt = SYSTEM.indexOf('\n\nTone:');
const ctxAt = SYSTEM.indexOf(marker);
if (ctxAt < 0 || toneAt < ctxAt) throw new Error('system prompt shape changed');
const system =
  '// GENERATED by scripts/gen-engine.js from counter.html. Do not edit by hand.\n' +
  '// The creator-specific context block is NOT included: the server builds it from validated request data.\n' +
  'export const SYSTEM_RULES = ' + JSON.stringify(SYSTEM.slice(0, ctxAt).trimEnd()) + ';\n' +
  'export const SYSTEM_TONE = ' + JSON.stringify(SYSTEM.slice(toneAt).trim()) + ';\n';

const targets = [['lib/engine.js', engine], ['lib/system.js', system]];
if (process.argv.includes('--check')) {
  let stale = false;
  for (const [f, text] of targets) {
    const p = path.join(root, f);
    const same = fs.existsSync(p) && fs.readFileSync(p, 'utf8') === text;
    console.log((same ? 'in sync  ' : 'STALE    ') + f);
    if (!same) stale = true;
  }
  process.exit(stale ? 1 : 0);
}
fs.mkdirSync(path.join(root, 'lib'), { recursive: true });
for (const [f, text] of targets) fs.writeFileSync(path.join(root, f), text);
console.log('Wrote lib/engine.js and lib/system.js');
